// Advanced: normalize heterogeneous per-system log shapes into one schema,
// categorize, collapse near-duplicates with a count, score, and trim for the LLM.
// Also computes FULL per-system and per-category totals (not just the trimmed
// top-N) so downstream coverage-gap and spike-detection checks see everything.
const cfg = $('Set - Config').first().json;
const response = $input.first().json;
const rawEvents = response.events || response.logs || response.hits || [];

function classifyCategory(e) {
  const text = JSON.stringify(e).toLowerCase();
  if (/failed login|authentication failure|invalid password/.test(text)) return 'auth_failure';
  if (/privilege escalation|sudo|admin rights granted/.test(text)) return 'privilege_escalation';
  if (/malware|virus|trojan|ransomware/.test(text)) return 'malware';
  if (/firewall|blocked connection|denied/.test(text)) return 'network_block';
  if (/anomal|unusual|geo.?velocity/.test(text)) return 'anomaly';
  if (/data exfil|large download|unusual transfer/.test(text)) return 'data_exfiltration';
  return 'other';
}

function normalizeEvent(e) {
  return {
    system: e.system || e.source || e.index || 'unknown',
    timestamp: e.timestamp || e['@timestamp'] || e.time || null,
    rawSeverity: String(e.severity || e.level || e.priority || '').toLowerCase(),
    category: classifyCategory(e),
    sourceIp: e.sourceIp || e.src_ip || e.clientIp || null,
    user: e.user || e.username || e.actor || null,
    message: e.message || e.msg || e.description || JSON.stringify(e).slice(0, 200)
  };
}

const CATEGORY_WEIGHT = { malware: 40, privilege_escalation: 35, data_exfiltration: 40, anomaly: 20, auth_failure: 10, network_block: 8, other: 5 };
const SEVERITY_WEIGHT = { critical: 30, high: 20, medium: 10, low: 5, info: 0 };

const normalized = rawEvents.map(normalizeEvent).map(ev => ({
  ...ev,
  severityScore: (CATEGORY_WEIGHT[ev.category] || 5) + (SEVERITY_WEIGHT[ev.rawSeverity] || 0)
}));

// Collapse repeated near-identical events (same system+category+sourceIp+user) into one, with a count
const grouped = new Map();
for (const ev of normalized) {
  const key = [ev.system, ev.category, ev.sourceIp, ev.user].join('|');
  if (!grouped.has(key)) {
    grouped.set(key, { ...ev, occurrenceCount: 1 });
  } else {
    const g = grouped.get(key);
    g.occurrenceCount += 1;
    g.severityScore = Math.max(g.severityScore, ev.severityScore);
  }
}
const collapsed = [...grouped.values()];

const byCategory = {};
collapsed.forEach(ev => { byCategory[ev.category] = (byCategory[ev.category] || 0) + ev.occurrenceCount; });

const bySystem = {};
collapsed.forEach(ev => { bySystem[ev.system] = (bySystem[ev.system] || 0) + ev.occurrenceCount; });

const topOffendingIps = {};
collapsed.forEach(ev => { if (ev.sourceIp) topOffendingIps[ev.sourceIp] = (topOffendingIps[ev.sourceIp] || 0) + ev.occurrenceCount; });
const topIpsSorted = Object.entries(topOffendingIps).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([ip, count]) => ({ ip, count }));

const NOTABLE_LIMIT = cfg.notableEventLimit || 25;
const notableEvents = collapsed.sort((a, b) => b.severityScore - a.severityScore).slice(0, NOTABLE_LIMIT);

return [{
  json: {
    ...cfg,
    totalRawEvents: rawEvents.length,
    totalCollapsedEvents: collapsed.length,
    byCategory,
    bySystem,
    topOffendingIps: topIpsSorted,
    notableEvents
  }
}];

// Rule-based fail-safe layer, independent of the LLM:
// (a) flags systems configured in systemsIncluded that reported zero events
//     this cycle (possible logging pipeline failure / blind spot)
// (b) flags categories whose count today is a statistical outlier vs the
//     recent rolling baseline (z-score based spike detection), using
//     workflow static data scoped to THIS node to store daily category
//     history across runs
// (c) computes a deterministic escalation flag so a single AI mis-
//     classification can never suppress escalation on its own
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.categoryHistory) staticData.categoryHistory = [];

const configuredSystems = (item.systemsIncluded || '').split(',').map(s => s.trim()).filter(Boolean);
const bySystem = item.bySystem || {};
const coverageGaps = configuredSystems.filter(sys => !bySystem[sys] || bySystem[sys] === 0);

const rollingDays = item.rollingBaselineDays || 14;
const zThreshold = item.spikeZScoreThreshold || 2;
const recentHistory = staticData.categoryHistory.slice(-rollingDays);

function meanStd(values) {
  if (!values.length) return { mean: 0, std: 0 };
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
  return { mean, std: Math.sqrt(variance) };
}

const allCategories = new Set();
recentHistory.forEach(h => Object.keys(h.byCategory || {}).forEach(c => allCategories.add(c)));
Object.keys(item.byCategory || {}).forEach(c => allCategories.add(c));

const spikeCategories = [];
for (const cat of allCategories) {
  const pastValues = recentHistory.map(h => (h.byCategory || {})[cat] || 0);
  const { mean, std } = meanStd(pastValues);
  const todayCount = (item.byCategory || {})[cat] || 0;
  if (pastValues.length >= 3 && std > 0) {
    const z = (todayCount - mean) / std;
    if (z >= zThreshold && todayCount > mean) {
      spikeCategories.push({ category: cat, todayCount, baselineMean: Math.round(mean * 10) / 10, zScore: Math.round(z * 100) / 100 });
    }
  }
}

const criticalCategories = item.criticalCategoriesForRuleBasedEscalation || ['malware', 'privilege_escalation', 'data_exfiltration'];
const criticalSystems = item.criticalSystemsForCoverageCheck || [];

const criticalCategoryHit = criticalCategories.some(c => (item.byCategory || {})[c] > 0);
const criticalSpike = spikeCategories.some(s => criticalCategories.includes(s.category));
const criticalCoverageGap = coverageGaps.some(sys => criticalSystems.includes(sys));

const ruleBasedEscalationReasons = [];
if (criticalCategoryHit) ruleBasedEscalationReasons.push('One or more critical-category events (malware/privilege escalation/data exfiltration) detected.');
if (criticalSpike) ruleBasedEscalationReasons.push('Statistically significant spike in a critical category vs the ' + rollingDays + '-day baseline.');
if (criticalCoverageGap) ruleBasedEscalationReasons.push('A critical logging source (' + coverageGaps.filter(s => criticalSystems.includes(s)).join(', ') + ') reported zero events - possible logging pipeline failure.');

const ruleBasedEscalationRequired = ruleBasedEscalationReasons.length > 0;

// Append today's category counts to the rolling baseline for tomorrow's comparison.
staticData.categoryHistory.push({ date: new Date().toISOString().slice(0, 10), byCategory: item.byCategory || {} });
if (staticData.categoryHistory.length > 60) staticData.categoryHistory.shift();

return [{
  json: {
    ...item,
    coverageGaps,
    spikeCategories,
    ruleBasedEscalationRequired,
    ruleBasedEscalationReasons
  }
}];

parameters.text:
=You are a security operations analyst preparing a daily briefing for a busy team. Time window: last {{ $json.timeRangeHours }} hours. Systems covered: {{ $json.systemsIncluded }}.

Event volume: {{ $json.totalRawEvents }} raw events, {{ $json.totalCollapsedEvents }} distinct events after collapsing repeats.
Breakdown by category: {{ JSON.stringify($json.byCategory) }}
Top source IPs by event count: {{ JSON.stringify($json.topOffendingIps) }}

A deterministic pre-check (not you) already found:
- Logging coverage gaps (systems with zero events this cycle): {{ $json.coverageGaps.length ? $json.coverageGaps.join(', ') : 'none' }}
- Statistical volume spikes vs the rolling baseline: {{ $json.spikeCategories.length ? $json.spikeCategories.map(s => s.category + ' (' + s.todayCount + ' vs avg ' + s.baselineMean + ')').join(', ') : 'none' }}

Most severe individual events (already trimmed to the top {{ $json.notableEvents.length }}):
{{ JSON.stringify($json.notableEvents) }}

Write a concise briefing that accounts for the coverage gaps and spikes above where relevant. Only recommend escalation (escalationRequired: true) for genuinely urgent situations — active malware, confirmed privilege escalation, likely data exfiltration, a clear coordinated attack pattern, or a critical coverage gap — not routine noise like isolated failed logins. Note that escalation may also be forced independently by the deterministic pre-check even if you set this to false.

Return ONLY a JSON object (no markdown fences, no commentary) with keys: executiveSummary (3-5 sentences, plain English, no jargon dump), criticalFindings (array of short strings, empty if none), recommendedActions (array of short strings, empty if none), overallRiskLevel ('low'|'medium'|'high'|'critical'), escalationRequired (boolean).

