// Advanced: safe JSON parse, combine the AI's judgment with the deterministic
// rule-based fail-safe from the previous node (so escalation is never solely
// dependent on the LLM getting it right), build TWO genuinely different
// artifacts from one summary, and persist today's outcome (via GLOBAL workflow
// static data, shared across nodes/runs) so the weekly trend digest has
// something to aggregate.
const item = $input.first().json;
const raw = item.text || item.output || item.response || '{}';
const ctx = $('JS - Detect Coverage Gaps & Spike Score').first().json;

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    executiveSummary: String(raw),
    criticalFindings: [],
    recommendedActions: [],
    overallRiskLevel: 'unknown',
    escalationRequired: false
  };
}

const criticalFindings = Array.isArray(parsed.criticalFindings) ? parsed.criticalFindings : [];
const recommendedActions = Array.isArray(parsed.recommendedActions) ? parsed.recommendedActions : [];
const overallRiskLevel = parsed.overallRiskLevel || 'unknown';

const finalEscalationRequired = !!parsed.escalationRequired || !!ctx.ruleBasedEscalationRequired;
const escalationReasons = [
  ...(parsed.escalationRequired ? ['AI flagged this as requiring escalation.'] : []),
  ...(ctx.ruleBasedEscalationReasons || [])
];

const RISK_EMOJI = { critical: '\uD83D\uDD34', high: '\uD83D\uDFE0', medium: '\uD83D\uDFE1', low: '\uD83D\uDFE2', unknown: '\u26AA' };

const coverageNote = ctx.coverageGaps && ctx.coverageGaps.length
  ? '\n\n⚠️ No events reported by: ' + ctx.coverageGaps.join(', ') + ' (possible logging gap).'
  : '';
const spikeNote = ctx.spikeCategories && ctx.spikeCategories.length
  ? '\n\n📈 Volume spike vs baseline: ' + ctx.spikeCategories.map(s => s.category + ' (' + s.todayCount + ' vs avg ' + s.baselineMean + ')').join(', ') + '.'
  : '';

const whatsappText = (RISK_EMOJI[overallRiskLevel] || RISK_EMOJI.unknown) + ' Daily Security Briefing (' + overallRiskLevel.toUpperCase() + ')\n\n'
  + parsed.executiveSummary + '\n\n'
  + (criticalFindings.length
      ? 'Critical findings:\n' + criticalFindings.slice(0, 3).map(f => '- ' + f).join('\n') + (criticalFindings.length > 3 ? '\n...and ' + (criticalFindings.length - 3) + ' more (see email)' : '')
      : 'No critical findings today.')
  + coverageNote + spikeNote
  + '\n\nEvents reviewed: ' + ctx.totalRawEvents + ' raw / ' + ctx.totalCollapsedEvents + ' after dedup.';

const categoryRows = Object.entries(ctx.byCategory || {}).map(([cat, count]) => '<tr><td>' + cat + '</td><td>' + count + '</td></tr>').join('');
const ipRows = (ctx.topOffendingIps || []).map(i => '<tr><td>' + i.ip + '</td><td>' + i.count + '</td></tr>').join('');
const gapRows = (ctx.coverageGaps || []).map(s => '<li>' + s + '</li>').join('') || '<li>None</li>';
const spikeRows = (ctx.spikeCategories || []).map(s => '<li>' + s.category + ': ' + s.todayCount + ' today vs ' + s.baselineMean + ' average (z=' + s.zScore + ')</li>').join('') || '<li>None</li>';
const escalationReasonRows = escalationReasons.map(r => '<li>' + r + '</li>').join('') || '<li>N/A</li>';

const emailHtml = '<h2>Daily Security Briefing — ' + overallRiskLevel.toUpperCase() + ' risk</h2>'
  + '<p>' + parsed.executiveSummary + '</p>'
  + '<h3>Critical Findings</h3><ul>' + (criticalFindings.map(f => '<li>' + f + '</li>').join('') || '<li>None</li>') + '</ul>'
  + '<h3>Recommended Actions</h3><ul>' + (recommendedActions.map(a => '<li>' + a + '</li>').join('') || '<li>None</li>') + '</ul>'
  + '<h3>Event Breakdown by Category</h3><table border="1" cellpadding="4"><tr><th>Category</th><th>Count</th></tr>' + categoryRows + '</table>'
  + '<h3>Top Source IPs</h3><table border="1" cellpadding="4"><tr><th>IP</th><th>Event Count</th></tr>' + ipRows + '</table>'
  + '<h3>Logging Coverage Gaps</h3><ul>' + gapRows + '</ul>'
  + '<h3>Volume Spikes vs Baseline</h3><ul>' + spikeRows + '</ul>'
  + '<h3>Why Escalation Was ' + (finalEscalationRequired ? '' : 'Not ') + 'Required</h3><ul>' + escalationReasonRows + '</ul>'
  + '<p>Total raw events: ' + ctx.totalRawEvents + ' | After deduplication: ' + ctx.totalCollapsedEvents + '</p>';

// Persist today's outcome for the weekly trend digest (GLOBAL static data,
// shared across nodes - separate from the per-node rolling baseline kept
// by the coverage/spike-detection node).
const globalStaticData = $getWorkflowStaticData('global');
if (!globalStaticData.dailyHistory) globalStaticData.dailyHistory = [];
globalStaticData.dailyHistory.push({
  date: new Date().toISOString().slice(0, 10),
  overallRiskLevel,
  escalationRequired: finalEscalationRequired,
  ruleBasedEscalationRequired: ctx.ruleBasedEscalationRequired,
  byCategory: ctx.byCategory,
  topOffendingIps: ctx.topOffendingIps,
  coverageGaps: ctx.coverageGaps,
  spikeCategories: ctx.spikeCategories
});
if (globalStaticData.dailyHistory.length > 35) globalStaticData.dailyHistory.shift();

return [{
  json: {
    ...ctx,
    executiveSummary: parsed.executiveSummary || '',
    criticalFindings,
    recommendedActions,
    overallRiskLevel,
    escalationRequired: finalEscalationRequired,
    escalationReasons,
    whatsappText,
    emailHtml
  }
}];

// The Wait node above resumes either via an explicit acknowledgment webhook
// call from the security lead, or automatically after escalationWaitTimeoutHours
// if nobody responds. Distinguish the two so an unacknowledged critical alert
// doesn't just quietly go out on schedule - it also notifies a backup contact.
const item = $input.first().json;
// A real webhook resume carries whatever body the security lead's client sent;
// a timeout resume carries no such payload. Treat presence of an explicit
// 'acknowledgedBy' field as proof of a genuine human acknowledgment.
const wasAcknowledged = !!(item.body && item.body.acknowledgedBy);
const acknowledgedBy = wasAcknowledged ? item.body.acknowledgedBy : null;

const analystNote = wasAcknowledged
  ? ('Acknowledged by ' + acknowledgedBy + ' before dispatch.')
  : ('No acknowledgment received within ' + (item.escalationWaitTimeoutHours || 4) + 'h - auto-dispatched, backup on-call notified.');

return [{
  json: {
    ...item,
    wasAcknowledged,
    acknowledgedBy,
    analystNote,
    escalationTimedOut: !wasAcknowledged
  }
}];

