// Aggregates the last 7 daily runs (persisted via GLOBAL workflow static
// data by the daily flow's Parse node) into a week-over-week trend report:
// category volume trend, escalation count, and the most persistent offending
// IPs across the week - things a single daily briefing can't show on its own.
const cfg = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const history = staticData.dailyHistory || [];

const last7 = history.slice(-7);
const prev7 = history.slice(-14, -7);

function sumByCategory(entries) {
  const totals = {};
  entries.forEach(e => Object.entries(e.byCategory || {}).forEach(([cat, count]) => { totals[cat] = (totals[cat] || 0) + count; }));
  return totals;
}

const last7Totals = sumByCategory(last7);
const prev7Totals = sumByCategory(prev7);

const categoryTrend = Object.keys({ ...last7Totals, ...prev7Totals }).map(cat => {
  const current = last7Totals[cat] || 0;
  const previous = prev7Totals[cat] || 0;
  const deltaPct = previous > 0 ? Math.round(((current - previous) / previous) * 1000) / 10 : (current > 0 ? 100 : 0);
  return { category: cat, currentWeek: current, previousWeek: previous, deltaPct };
}).sort((a, b) => b.currentWeek - a.currentWeek);

const ipCounts = {};
last7.forEach(e => (e.topOffendingIps || []).forEach(i => { ipCounts[i.ip] = (ipCounts[i.ip] || 0) + i.count; }));
const persistentOffenders = Object.entries(ipCounts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([ip, count]) => ({ ip, count }));

const escalationCount = last7.filter(e => e.escalationRequired || e.ruleBasedEscalationRequired).length;
const daysWithCoverageGaps = last7.filter(e => (e.coverageGaps || []).length > 0).length;

const rows = categoryTrend.map(c => '<tr><td>' + c.category + '</td><td>' + c.currentWeek + '</td><td>' + c.previousWeek + '</td><td>' + (c.deltaPct > 0 ? '+' : '') + c.deltaPct + '%</td></tr>').join('');
const ipRows = persistentOffenders.map(i => '<tr><td>' + i.ip + '</td><td>' + i.count + '</td></tr>').join('');

const digestHtml = '<h2>Weekly Security Trend Digest</h2>'
  + '<p>Covering the last ' + last7.length + ' recorded day(s). Escalations this week: ' + escalationCount + '. Days with a logging coverage gap: ' + daysWithCoverageGaps + '.</p>'
  + '<h3>Category Volume: This Week vs Previous Week</h3><table border="1" cellpadding="4"><tr><th>Category</th><th>This Week</th><th>Previous Week</th><th>Change</th></tr>' + rows + '</table>'
  + '<h3>Most Persistent Offending IPs This Week</h3><table border="1" cellpadding="4"><tr><th>IP</th><th>Total Events</th></tr>' + ipRows + '</table>';

return [{
  json: {
    ...cfg,
    categoryTrend,
    persistentOffenders,
    escalationCount,
    daysWithCoverageGaps,
    digestHtml,
    digestGeneratedAt: new Date().toISOString()
  }
}];
